PRAGMA foreign_keys=ON;
CREATE TABLE dim_supplier ("supplier_id" TEXT NOT NULL PRIMARY KEY, "supplier_name" TEXT NOT NULL, "country" TEXT NOT NULL);
CREATE TABLE dim_customer ("customer_id" TEXT NOT NULL PRIMARY KEY, "customer_name" TEXT NOT NULL, "country" TEXT NOT NULL);
CREATE TABLE dim_facility ("facility_id" TEXT NOT NULL PRIMARY KEY, "facility_name" TEXT NOT NULL, "city" TEXT NOT NULL);
CREATE TABLE dim_product ("product_id" TEXT NOT NULL PRIMARY KEY, "product_description" TEXT NOT NULL, "category" TEXT NOT NULL, "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')), "supplier_id" TEXT NOT NULL REFERENCES dim_supplier(supplier_id));
CREATE INDEX ix_dim_product_supplier_id ON dim_product(supplier_id);
CREATE TABLE dim_material ("material_id" TEXT NOT NULL PRIMARY KEY, "material_name" TEXT NOT NULL, "supplier_id" TEXT NOT NULL REFERENCES dim_supplier(supplier_id), "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')));
CREATE INDEX ix_dim_material_supplier_id ON dim_material(supplier_id);
CREATE TABLE dim_warehouse ("warehouse_id" TEXT NOT NULL PRIMARY KEY, "facility_id" TEXT NOT NULL REFERENCES dim_facility(facility_id), "warehouse_name" TEXT NOT NULL);
CREATE INDEX ix_dim_warehouse_facility_id ON dim_warehouse(facility_id);
CREATE TABLE fact_sales_order ("order_id" TEXT NOT NULL PRIMARY KEY, "customer_id" TEXT NOT NULL REFERENCES dim_customer(customer_id), "product_id" TEXT NOT NULL REFERENCES dim_product(product_id), "facility_id" TEXT NOT NULL REFERENCES dim_facility(facility_id), "order_date" TEXT NOT NULL CHECK (length("order_date")=10 AND date("order_date") IS NOT NULL), "quantity" REAL NOT NULL CHECK ("quantity" >= 0), "unit_price" REAL NOT NULL CHECK ("unit_price" >= 0), "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')));
CREATE INDEX ix_fact_sales_order_customer_id ON fact_sales_order(customer_id);
CREATE INDEX ix_fact_sales_order_product_id ON fact_sales_order(product_id);
CREATE INDEX ix_fact_sales_order_facility_id ON fact_sales_order(facility_id);
CREATE INDEX ix_fact_sales_order_date ON fact_sales_order(order_date);
CREATE TABLE fact_sales_order_line ("line_id" TEXT NOT NULL PRIMARY KEY, "order_id" TEXT NOT NULL REFERENCES fact_sales_order(order_id), "product_id" TEXT NOT NULL REFERENCES dim_product(product_id), "order_date" TEXT NOT NULL CHECK (length("order_date")=10 AND date("order_date") IS NOT NULL), "quantity" REAL NOT NULL CHECK ("quantity" >= 0), "unit_price" REAL NOT NULL CHECK ("unit_price" >= 0), "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')));
CREATE INDEX ix_fact_sales_order_line_order_id ON fact_sales_order_line(order_id);
CREATE INDEX ix_fact_sales_order_line_product_id ON fact_sales_order_line(product_id);
CREATE INDEX ix_fact_sales_order_line_date ON fact_sales_order_line(order_date);
CREATE TABLE fact_production ("production_id" TEXT NOT NULL PRIMARY KEY, "product_id" TEXT NOT NULL REFERENCES dim_product(product_id), "facility_id" TEXT NOT NULL REFERENCES dim_facility(facility_id), "material_id" TEXT NOT NULL REFERENCES dim_material(material_id), "production_date" TEXT NOT NULL CHECK (length("production_date")=10 AND date("production_date") IS NOT NULL), "quantity" REAL NOT NULL CHECK ("quantity" >= 0), "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')));
CREATE INDEX ix_fact_production_product_id ON fact_production(product_id);
CREATE INDEX ix_fact_production_facility_id ON fact_production(facility_id);
CREATE INDEX ix_fact_production_material_id ON fact_production(material_id);
CREATE INDEX ix_fact_production_date ON fact_production(production_date);
CREATE TABLE fact_inventory ("inventory_id" TEXT NOT NULL PRIMARY KEY, "product_id" TEXT NOT NULL REFERENCES dim_product(product_id), "facility_id" TEXT NOT NULL REFERENCES dim_facility(facility_id), "warehouse_id" TEXT NOT NULL REFERENCES dim_warehouse(warehouse_id), "stock_date" TEXT NOT NULL CHECK (length("stock_date")=10 AND date("stock_date") IS NOT NULL), "quantity" REAL NOT NULL CHECK ("quantity" >= 0), "uom" TEXT NOT NULL CHECK (uom IN ('EA','KG','L')));
CREATE INDEX ix_fact_inventory_product_id ON fact_inventory(product_id);
CREATE INDEX ix_fact_inventory_facility_id ON fact_inventory(facility_id);
CREATE INDEX ix_fact_inventory_warehouse_id ON fact_inventory(warehouse_id);
CREATE INDEX ix_fact_inventory_date ON fact_inventory(stock_date);
CREATE TABLE fact_shipment ("shipment_id" TEXT NOT NULL PRIMARY KEY, "order_id" TEXT NOT NULL REFERENCES fact_sales_order(order_id), "facility_id" TEXT NOT NULL REFERENCES dim_facility(facility_id), "carrier" TEXT NOT NULL, "ship_date" TEXT NOT NULL CHECK (length("ship_date")=10 AND date("ship_date") IS NOT NULL), "promised_date" TEXT NOT NULL CHECK (length("promised_date")=10 AND date("promised_date") IS NOT NULL), "delivery_date" TEXT NOT NULL CHECK (length("delivery_date")=10 AND date("delivery_date") IS NOT NULL), "quantity" REAL NOT NULL CHECK ("quantity" >= 0));
CREATE INDEX ix_fact_shipment_order_id ON fact_shipment(order_id);
CREATE INDEX ix_fact_shipment_facility_id ON fact_shipment(facility_id);
CREATE INDEX ix_fact_shipment_date ON fact_shipment(ship_date);
CREATE TABLE ref_uom (uom TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE ref_product_category (category TEXT PRIMARY KEY);
CREATE TABLE dq_run (run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, completed_at TEXT NOT NULL, as_of TEXT NOT NULL, overall_score REAL CHECK(overall_score BETWEEN 0 AND 100), raw_records INTEGER, curated_records INTEGER, quarantined_records INTEGER, rule_count INTEGER, exception_count INTEGER, weights_json TEXT NOT NULL, input_hash TEXT NOT NULL);
CREATE TABLE dq_rule (rule_id TEXT PRIMARY KEY, rule_name TEXT, description TEXT, dimension TEXT, severity TEXT, source_system TEXT, table_name TEXT, column_name TEXT, validation_logic TEXT, phase TEXT, reject INTEGER, active INTEGER, parameters TEXT);
CREATE TABLE dq_result (run_id TEXT REFERENCES dq_run(run_id), rule_id TEXT REFERENCES dq_rule(rule_id), records_checked INTEGER, records_passed INTEGER, records_failed INTEGER, pass_rate REAL, failure_rate REAL, severity TEXT, executed_at TEXT, affected_records TEXT, PRIMARY KEY(run_id,rule_id), CHECK(records_passed+records_failed=records_checked));
CREATE TABLE dq_exception (exception_id TEXT PRIMARY KEY, run_id TEXT REFERENCES dq_run(run_id), rule_id TEXT REFERENCES dq_rule(rule_id), source_system TEXT, table_name TEXT, record_key TEXT, source_row INTEGER, column_name TEXT, current_value TEXT, expected_condition TEXT, severity TEXT CHECK(severity IN ('Critical','High','Medium','Low')), status TEXT CHECK(status IN ('Open','In Review','Resolved','Accepted')), detected_at TEXT, assigned_to TEXT, resolution_note TEXT, resolved_at TEXT, facility_id TEXT, month TEXT);
CREATE INDEX ix_exception_status ON dq_exception(status,severity);
CREATE INDEX ix_exception_facility ON dq_exception(facility_id);
CREATE TABLE dq_check (run_id TEXT REFERENCES dq_run(run_id), rule_id TEXT REFERENCES dq_rule(rule_id), table_name TEXT, source_row INTEGER, source_system TEXT, dimension TEXT, facility_id TEXT, month TEXT, passed INTEGER CHECK(passed IN (0,1)), PRIMARY KEY(run_id,rule_id,source_row));
CREATE INDEX ix_check_scope ON dq_check(source_system,facility_id,month);
CREATE TABLE dq_score (scope TEXT, group_name TEXT, score REAL, checks INTEGER, failed_checks INTEGER, PRIMARY KEY(scope,group_name));
CREATE TABLE metadata_catalog (table_name TEXT, field_name TEXT, business_name TEXT, description TEXT, data_type TEXT, source_system TEXT, sensitivity TEXT, owner TEXT, refresh_frequency TEXT, critical_data_element INTEGER, PRIMARY KEY(table_name,field_name));
CREATE TABLE business_glossary (term TEXT PRIMARY KEY, definition TEXT, business_owner TEXT, related_field TEXT, calculation TEXT);
CREATE TABLE data_lineage (lineage_id TEXT PRIMARY KEY, source TEXT, transformation TEXT, target TEXT, description TEXT);
CREATE TABLE data_owner (table_name TEXT PRIMARY KEY, owner TEXT, steward TEXT, responsibility TEXT);
CREATE TABLE profiling_result (table_name TEXT, stage TEXT, column_name TEXT, row_count INTEGER, column_count INTEGER, data_type TEXT, null_count INTEGER, null_percentage REAL, unique_count INTEGER, duplicate_count INTEGER, row_duplicate_count INTEGER, min_value TEXT, max_value TEXT, mean_value REAL, median_value REAL, sample_values TEXT, PRIMARY KEY(table_name,stage,column_name));
CREATE TABLE executive_kpis (total_orders INTEGER, order_quantity REAL, average_order_quantity REAL, sales_value REAL, production_quantity REAL, inventory_quantity REAL, inventory_snapshot_date TEXT, shipments INTEGER, delivered_shipments INTEGER, on_time_delivery_rate REAL, average_delivery_delay REAL, late_shipments INTEGER, order_fulfillment_rate REAL, dq_score REAL, failed_rules INTEGER, open_exceptions INTEGER, critical_exceptions INTEGER);
CREATE TABLE kpi_daily (date TEXT PRIMARY KEY, total_orders INTEGER, order_quantity REAL, production_quantity REAL, inventory_quantity REAL, shipments INTEGER, late_shipments INTEGER, on_time_delivery_rate REAL);
CREATE TABLE kpi_monthly (month TEXT PRIMARY KEY, total_orders INTEGER, order_quantity REAL, production_quantity REAL, inventory_quantity REAL, shipments INTEGER, late_shipments INTEGER, on_time_delivery_rate REAL);
CREATE TABLE facility_performance (facility_id TEXT PRIMARY KEY REFERENCES dim_facility(facility_id), facility_name TEXT, total_orders INTEGER, order_quantity REAL, production_quantity REAL, inventory_quantity REAL, shipments INTEGER, late_shipments INTEGER, on_time_delivery_rate REAL);
CREATE TABLE product_performance (product_id TEXT PRIMARY KEY REFERENCES dim_product(product_id), category TEXT, total_orders INTEGER, order_quantity REAL, production_quantity REAL, inventory_quantity REAL, shipments INTEGER, late_shipments INTEGER, on_time_delivery_rate REAL);
CREATE TABLE category_performance (category TEXT PRIMARY KEY, total_orders INTEGER, order_quantity REAL, production_quantity REAL, inventory_quantity REAL, shipments INTEGER, late_shipments INTEGER, on_time_delivery_rate REAL);
CREATE TABLE inventory_trend (month TEXT, facility_id TEXT, product_id TEXT, quantity REAL, snapshot_date TEXT, PRIMARY KEY(month,facility_id,product_id));
CREATE TABLE governance_coverage (table_name TEXT PRIMARY KEY, fields INTEGER, documented_fields INTEGER, owned_fields INTEGER, critical_fields INTEGER, documented_critical_fields INTEGER, lineage_edges INTEGER, glossary_terms INTEGER, metadata_coverage REAL, ownership_coverage REAL, critical_coverage REAL);
